import React, { useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';

const Navbar = () => {
  const { user, logout, isAuthenticated } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const navItems = [
    { path: '/dashboard', label: 'Dashboard', icon: Home },
    { path: '/animals', label: 'Animals', icon: Users },
    { path: '/breeding', label: 'Breeding', icon: Heart },
    { path: '/breeding-box', label: 'Breeding Box', icon: Box },
    { path: '/ai-advisor', label: 'AI Advisor', icon: Brain },
    { path: '/schedule', label: 'Schedule', icon: Calendar },
  ];

  const isActive = (path) => location.pathname === path;

  if (!isAuthenticated) {
    return null;
  }

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <Link to="/dashboard" className="navbar-brand">
          <Leaf className="navbar-logo" />
          <span className="navbar-title">FarmBreed AI</span>
        </Link>

        <div className={`navbar-menu ${isMobileMenuOpen ? 'active' : ''}`}>
          <div className="navbar-nav">
            {navItems.map(({ path, label, icon: Icon }) => (
              <Link
                key={path}
                to={path}
                className={`navbar-link ${isActive(path) ? 'active' : ''}`}
                onClick={() => setIsMobileMenuOpen(false)}
              >
                <Icon className="navbar-icon" />
                <span>{label}</span>
              </Link>
            ))}
          </div>

          <div className="navbar-user">
            <div className="user-info">
              <div className="user-avatar">
                <User size={20} />
              </div>
              <div className="user-details">
                <div className="user-name">{user?.firstName} {user?.lastName}</div>
                <div className="user-farm">{user?.farmName}</div>
              </div>
            </div>
            <Link to="/profile" className="navbar-link">
              <User className="navbar-icon" />
              <span>Profile</span>
            </Link>
            <button onClick={handleLogout} className="navbar-link logout-btn">
              <LogOut className="navbar-icon" />
              <span>Logout</span>
            </button>
          </div>
        </div>

        <button
          className="navbar-toggle"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>
    </nav>
  );
};

export default Navbar;
